    }
  }

  const jetPlan = selectedJet ?? nearestJet;
  let chosen: CandidatePlan | null = wetStartEgress ?? selectedDry;
  let mode: AgentSurfaceRouteMode = wetStartEgress ? 'jetpack' : 'walk';
  let reason: AgentSurfaceRouteReason = wetStartEgress
    ? 'wet-start-egress'
